#!/usr/bin/env python3
import sys, os, csv, json, gzip, io
from datetime import datetime, timedelta, timezone, date, time as dtime
from zoneinfo import ZoneInfo
from fractions import Fraction
from decimal import Decimal

UTC = timezone.utc


def read_text(path):
    with open(path, 'rb') as f:
        b = f.read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b.decode('utf-8-sig')


def lines_of(text):
    return [l for l in text.replace('\r\n', '\n').replace('\r', '\n').split('\n') if l.strip() != '']


def to_utc(naive, tz, dst=None):
    """naive local -> epoch seconds. dst: True/False picks the repeated occurrence; None = first."""
    a = naive.replace(tzinfo=tz, fold=0)
    b = naive.replace(tzinfo=tz, fold=1)
    if a.utcoffset() != b.utcoffset() and a.utcoffset() > b.utcoffset():
        pick = b if dst is False else a
    else:
        pick = a
    return int(pick.timestamp())


def std_offset(tz):
    y = 2026
    best = None
    for m in range(1, 13):
        d = datetime(y, m, 1, 12, tzinfo=tz)
        if not d.dst():
            return int(d.utcoffset().total_seconds())
        o = int(d.utcoffset().total_seconds())
        best = o if best is None else min(best, o)
    return best


def parse_abbr(text, tz):
    out = []
    hdr = None
    for row in csv.reader(lines_of(text)):
        row = [c.strip() for c in row]
        if 'Badge' in row and 'Punch' in row:
            hdr = {n: i for i, n in enumerate(row)}
            continue
        if hdr is None:
            continue
        g = lambda n: row[hdr[n]]
        mo, d, y = g('Date').split('/')
        t = g('Time').upper().split()
        hh, mm, ss = t[0].split(':')
        h = int(hh)
        if len(t) > 1:
            h = h % 12 + (12 if t[1] == 'PM' else 0)
        naive = datetime(int(y), int(mo), int(d), h, int(mm), int(ss))
        z = g('Zone').upper()
        dst = True if z.endswith('DT') else (False if z.endswith('ST') else None)
        out.append((g('Record'), g('Badge'), g('Punch').upper(), to_utc(naive, tz, dst)))
    return out


def parse_epoch(text, tz):
    out = []
    schema = 1
    for l in lines_of(text):
        o = json.loads(l)
        if 'schema' in o and 'heartbeat' not in o and 'id' not in o and 'punch_id' not in o:
            schema = int(o['schema'])
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            pid, emp, d, ts = o['punch_id'], o['employee'], o['direction'], int(o['epoch_ms']) // 1000
        else:
            pid, emp, d = o['id'], o['emp'], o['dir']
            ts = int(o['ts']) if 'ts' in o else int(o['ts_ms']) // 1000
        out.append((str(pid), emp, d.upper(), ts))
    return out


def parse_offset(text, tz):
    out = []
    r = csv.DictReader(io.StringIO('\n'.join(lines_of(text))), delimiter=';')
    for row in r:
        ev = row['event'].strip()
        d = 'IN' if ev == 'clock_in' else 'OUT'
        ts = int(datetime.fromisoformat(row['timestamp'].strip()).timestamp())
        out.append((row['punch_id'], row['employee'], d, ts))
    return out


def parse_legacy(text, tz):
    out = []
    off = std_offset(tz)
    default = off
    for l in lines_of(text):
        k = l[0]
        if k == 'H':
            s = l[13:18].strip()
            if s and s[0] in '+-' and len(s) == 5:
                v = (int(s[1:3]) * 3600 + int(s[3:5]) * 60) * (1 if s[0] == '+' else -1)
                off = v
            else:
                off = default
        elif k == 'D':
            pid = l[1:9]
            badge = l[9:15].strip()
            d = 'IN' if l[15] == 'I' else 'OUT'
            dt = datetime.strptime(l[16:30], '%Y%m%d%H%M%S')
            ts = int(dt.replace(tzinfo=UTC).timestamp()) - off
            out.append((pid, 'E' + badge, d, ts))
    return out


def parse_de(text, tz):
    out = []
    r = csv.DictReader(io.StringIO('\n'.join(lines_of(text))), delimiter='\t')
    for row in r:
        row = {k.strip(): v.strip() for k, v in row.items()}
        naive = datetime.strptime(row['Datum'] + ' ' + row['Uhrzeit'], '%d.%m.%Y %H:%M')
        z = row['Zeitzone'].upper()
        dst = True if z == 'MESZ' else (False if z == 'MEZ' else None)
        out.append((row['Nr'], row['Ausweis'], 'IN' if row['Buchung'] == 'K' else 'OUT', to_utc(naive, tz, dst)))
    return out


def parse_localcsv(text, tz):
    out = []
    for row in csv.DictReader(io.StringIO('\n'.join(lines_of(text)))):
        naive = datetime.strptime(row['local_time'].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((row['punch_ref'].strip(), row['employee_id'].strip(), row['direction'].strip().upper(), to_utc(naive, tz)))
    return out


def parse_localjsonl(text, tz):
    out = []
    for l in lines_of(text):
        o = json.loads(l)
        p = o.get('punch')
        if not p:
            continue
        naive = datetime.strptime(p['at'].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((str(p['id']), p['badge'], p['type'].upper(), to_utc(naive, tz)))
    return out


PARSERS = {'abbr-csv': parse_abbr, 'epoch-jsonl': parse_epoch, 'offset-csv': parse_offset,
           'legacy-fixed': parse_legacy, 'de-tsv': parse_de, 'local-csv': parse_localcsv,
           'local-jsonl': parse_localjsonl}


def walk(d):
    for root, _, files in os.walk(d):
        for f in sorted(files):
            yield os.path.join(root, f)


def main(inp, outp):
    period = json.load(open(os.path.join(inp, 'period.json')))
    start = date.fromisoformat(period['start'])
    end = date.fromisoformat(period['end'])
    cutoff = datetime.fromisoformat(period['corrections_cutoff'].replace('Z', '+00:00')).timestamp()
    sites = {}
    with open(os.path.join(inp, 'sites.csv'), encoding='utf-8-sig', newline='') as f:
        for r in csv.DictReader(f):
            sites[r['site'].strip()] = (ZoneInfo(r['timezone'].strip()), r['format'].strip())
    emps = {}
    with open(os.path.join(inp, 'employees.csv'), encoding='utf-8-sig', newline='') as f:
        for r in csv.DictReader(f):
            emps[r['employee_id'].strip()] = r['home_site'].strip()
    rates = {}
    with open(os.path.join(inp, 'rates.csv'), encoding='utf-8-sig', newline='') as f:
        for r in csv.DictReader(f):
            rates.setdefault(r['employee_id'].strip(), []).append(
                (date.fromisoformat(r['effective_from'].strip()), Fraction(Decimal(r['hourly_rate'].strip()))))
    for v in rates.values():
        v.sort()

    punches = {}  # (site,id) -> [emp, dir, ts]
    ever = set()
    for site, (tz, fmt) in sites.items():
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        for p in walk(d):
            for pid, emp, dr, ts in PARSERS[fmt](read_text(p), tz):
                k = (site, pid)
                ever.add(k)
                if k not in punches:
                    punches[k] = [emp.strip(), dr, ts]

    # corrections
    corr = []
    cdir = os.path.join(inp, 'corrections')
    if os.path.isdir(cdir):
        for p in walk(cdir):
            for r in csv.DictReader(io.StringIO('\n'.join(lines_of(read_text(p))))):
                r = {k: (v or '').strip() for k, v in r.items() if k}
                corr.append(r)
    def iss(r):
        return datetime.fromisoformat(r['issued_at'].replace('Z', '+00:00')).timestamp()
    corr = [r for r in corr if iss(r) <= cutoff]
    corr.sort(key=lambda r: (iss(r), r['correction_id']))
    applied = 0
    voided = set()
    for r in corr:
        k = (r['site'], r['punch_id'])
        a = r['action']
        if a == 'void':
            if k in punches and k not in voided:
                del punches[k]
                voided.add(k)
                applied += 1
        elif a == 'set':
            if k in punches:
                punches[k][2] = int(datetime.fromisoformat(r['time'].replace('Z', '+00:00')).timestamp())
                applied += 1
        elif a == 'add':
            if k not in ever:
                ever.add(k)
                punches[k] = [r['employee'], r['type'].upper(),
                              int(datetime.fromisoformat(r['time'].replace('Z', '+00:00')).timestamp())]
                applied += 1

    by_emp = {}
    for (site, pid), (emp, dr, ts) in punches.items():
        if emp in emps:
            by_emp.setdefault(emp, []).append((ts, 0 if dr == 'OUT' else 1, site, pid, dr))

    def rnd(ts, tz):
        off = int(datetime.fromtimestamp(ts, UTC).astimezone(tz).utcoffset().total_seconds())
        loc = ts + off
        return (loc + 180) // 360 * 360 - off

    exc = {'open_shifts': 0, 'orphan_outs': 0, 'duplicates_dropped': 0, 'corrections_applied': applied}
    result = {}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    totgross = 0
    for e, home in emps.items():
        htz = sites[home][0]
        wd = lambda ts: datetime.fromtimestamp(ts, UTC).astimezone(htz).date()
        in_p = lambda ts: start <= wd(ts) <= end
        pl = sorted(by_emp.get(e, []))
        kept = []
        for ts, _, site, pid, dr in pl:
            tz = sites[site][0]
            if kept and kept[-1][4] == dr and ts - kept[-1][0] <= 300:
                if in_p(rnd(ts, tz)):
                    exc['duplicates_dropped'] += 1
                continue
            kept.append((ts, 0, site, pid, dr, rnd(ts, tz)))
        shifts = []
        pend = None
        def openit(x):
            if in_p(x[5]):
                exc['open_shifts'] += 1
        for x in kept:
            if x[4] == 'IN':
                if pend:
                    openit(pend)
                pend = x
            else:
                if pend and x[5] - pend[5] <= 16 * 3600:
                    shifts.append((pend, x))
                    pend = None
                else:
                    if pend:
                        openit(pend)
                        pend = None
                    if in_p(x[5]):
                        exc['orphan_outs'] += 1
        if pend:
            openit(pend)
        shifts = [s for s in shifts if in_p(s[0][5])]
        shifts.sort(key=lambda s: s[0][5])
        rl = rates.get(e, [])
        daily = {}
        weekly = {}
        n = paid_t = ot_t = night_t = 0
        gross = Fraction(0)
        for i_, o_ in shifts:
            a, b = i_[5], o_[5]
            tz = sites[i_[2]][0]
            worked = max(0, (b - a) // 60)
            paid = worked - 30 if worked > 360 else worked
            # night
            night = 0
            la = datetime.fromtimestamp(a, UTC).astimezone(tz).date()
            lb = datetime.fromtimestamp(b, UTC).astimezone(tz).date()
            dd = la - timedelta(days=1)
            while dd <= lb:
                w0 = int(datetime.combine(dd, dtime(22), tzinfo=tz).timestamp())
                w1 = int(datetime.combine(dd + timedelta(days=1), dtime(6), tzinfo=tz).timestamp())
                lo, hi = max(a, w0), min(b, w1)
                if hi > lo:
                    night += (hi - lo) / 60
                dd += timedelta(days=1)
            night = min(int(night), paid)
            day = wd(a)
            used = daily.get(day, 0)
            dot = max(0, used + paid - max(used, 480))
            daily[day] = used + paid
            reg = paid - dot
            wk = day - timedelta(days=day.weekday())
            wu = weekly.get(wk, 0)
            wot = max(0, wu + reg - max(wu, 2400))
            weekly[wk] = wu + reg
            ot = dot + wot
            regular = paid - ot
            rate = None
            for ef, r in rl:
                if ef <= day:
                    rate = r
            rate = rate or Fraction(0)
            gross += rate * (regular + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            n += 1; paid_t += paid; ot_t += ot; night_t += night
        cents = int(gross * 100 + Fraction(1, 2) // 1) if False else (gross * 100 + Fraction(1, 2)).__floor__()
        result[e] = dict(shifts=n, paid_minutes=paid_t, overtime_minutes=ot_t, night_minutes=night_t,
                         gross='%d.%02d' % divmod(cents, 100))
        tot['shifts'] += n; tot['paid_minutes'] += paid_t; tot['overtime_minutes'] += ot_t
        tot['night_minutes'] += night_t
        totgross += cents
    tot['gross'] = '%d.%02d' % divmod(totgross, 100)
    with open(outp, 'w') as f:
        json.dump({'period': {'start': period['start'], 'end': period['end']}, 'employees': result,
                   'exceptions': exc, 'totals': tot}, f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
